import{_ as a,o as t,c as s,ag as o}from"./chunks/framework.1IVNT0ce.js";const d=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),n={name:"contributing.md"};function i(l,e,r,p,c,h){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Klix is small enough that individual changes can improve the framework quickly, but that also means each change has to respect the existing shape of the codebase. This guide explains how to work on the project without fighting that design.</p><h2 id="how-to-run-the-project-locally" tabindex="-1">How To Run The Project Locally <a class="header-anchor" href="#how-to-run-the-project-locally" aria-label="Permalink to &quot;How To Run The Project Locally&quot;">​</a></h2><p>Clone the repository, create a virtual environment, and install the package in editable mode:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> -m</span><span style="color:#C3E88D;"> venv</span><span style="color:#C3E88D;"> .venv</span></span>
<span class="line"><span style="color:#82AAFF;">source</span><span style="color:#C3E88D;"> .venv/bin/activate</span></span>
<span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> -m</span><span style="color:#C3E88D;"> pip</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> -e</span><span style="color:#C3E88D;"> .</span></span></code></pre></div><p>Run the example apps:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> examples/minimal.py</span></span>
<span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> examples/full_demo.py</span></span>
<span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> examples/chat_ai.py</span></span>
<span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> examples/ui_showcase.py</span></span></code></pre></div><p>Run the tests:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> -m</span><span style="color:#C3E88D;"> pytest</span><span style="color:#C3E88D;"> -q</span></span></code></pre></div><h2 id="what-a-good-contribution-looks-like" tabindex="-1">What A Good Contribution Looks Like <a class="header-anchor" href="#what-a-good-contribution-looks-like" aria-label="Permalink to &quot;What A Good Contribution Looks Like&quot;">​</a></h2><p>Good changes usually have these qualities:</p><ul><li>they solve one clear problem</li><li>they fit the current architecture instead of bypassing it</li><li>they keep the public API small</li><li>they include tests or example coverage where practical</li><li>they update documentation when behavior changes</li></ul><p>Klix is intentionally not a giant framework. Additions should earn their weight.</p><h2 id="how-to-add-features-correctly" tabindex="-1">How To Add Features Correctly <a class="header-anchor" href="#how-to-add-features-correctly" aria-label="Permalink to &quot;How To Add Features Correctly&quot;">​</a></h2><p>When you add a feature, work from the framework layers outward:</p><ol><li>decide whether it belongs in the core runtime, UI namespace, renderer, or an example</li><li>make the smallest change that fits that layer</li><li>keep the public API semantic and lightweight</li><li>validate behavior in a real example, not just in isolation</li></ol><p>Examples:</p><ul><li>a new visual helper probably belongs under <code>session.ui.output</code></li><li>a new prompt interaction probably belongs under <code>session.ui.input</code></li><li>lifecycle behavior probably belongs in <code>App</code>, events, or middleware</li></ul><p>If a feature requires reaching into many private attributes to work, the design probably needs another pass.</p><h2 id="coding-guidelines" tabindex="-1">Coding Guidelines <a class="header-anchor" href="#coding-guidelines" aria-label="Permalink to &quot;Coding Guidelines&quot;">​</a></h2><ul><li>Keep code readable and direct.</li><li>Prefer typed, explicit interfaces over loose dictionaries.</li><li>Reuse existing framework surfaces before creating new ones.</li><li>Use semantic theme keys instead of hardcoded styling in reusable components.</li><li>Do not introduce dependencies casually. Klix currently stays small on purpose.</li><li>Keep fallback and CI behavior in mind when working on UI features.</li></ul><h2 id="testing-expectations" tabindex="-1">Testing Expectations <a class="header-anchor" href="#testing-expectations" aria-label="Permalink to &quot;Testing Expectations&quot;">​</a></h2><p>Not every change needs a large test suite, but it should be verifiable.</p><p>Typical validation steps:</p><ul><li>run <code>pytest</code></li><li>run the relevant example app</li><li>verify interactive features in a real terminal when applicable</li></ul><p>For UI-heavy work, examples are especially valuable because terminal behavior is hard to understand from unit tests alone.</p><h2 id="documentation-expectations" tabindex="-1">Documentation Expectations <a class="header-anchor" href="#documentation-expectations" aria-label="Permalink to &quot;Documentation Expectations&quot;">​</a></h2><p>If behavior changes, update the docs in <code>docs/</code>.</p><p>The goal of the documentation set is that a developer can use Klix without reading the source. Keep that standard in mind when you change:</p><ul><li>public API</li><li>command flow</li><li>persistence behavior</li><li>component behavior</li></ul><h2 id="pull-requests-and-suggestions" tabindex="-1">Pull Requests And Suggestions <a class="header-anchor" href="#pull-requests-and-suggestions" aria-label="Permalink to &quot;Pull Requests And Suggestions&quot;">​</a></h2><p>Pull requests, bug reports, design suggestions, and documentation improvements are all useful contributions.</p><p>Helpful pull requests usually include:</p><ul><li>a clear problem statement</li><li>a focused change set</li><li>notes on how the change was validated</li></ul><p>If you are not sure whether a feature fits the project, opening an issue or discussion first is a good way to avoid wasted work.</p><h2 id="a-professional-baseline" tabindex="-1">A Professional Baseline <a class="header-anchor" href="#a-professional-baseline" aria-label="Permalink to &quot;A Professional Baseline&quot;">​</a></h2><p>Welcoming contributions does not mean lowering the bar. The framework is small enough that unclear abstractions, duplicate APIs, or loosely justified features can make it harder to maintain quickly.</p><p>Aim for:</p><ul><li>small changes</li><li>clear reasoning</li><li>honest docs</li><li>practical examples</li></ul><p>That is how Klix stays approachable as it grows.</p>`,40)])])}const b=a(n,[["render",i]]);export{d as __pageData,b as default};
